package com.teno.app;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

/** Team audio, identity review and voice profiles use the shared authenticated API. */
public final class TeamAudioActivity extends MainActivity {
    String teamId="",teamName="",memberId="",role="member",mid="";JSONArray members=new JSONArray();JSONObject meeting=new JSONObject();
    TeamAudioStore uploads;
    String endpoint(String p){return "/api/v1/teams/"+teamId+p;}
    @Override public void onBackPressed(){if(page.equals("team_audio")){finish();return;}overview();}
    @Override void home(){
        try{JSONObject team=new JSONObject(getIntent().getStringExtra("team"));teamId=team.getString("id");teamName=team.optString("name");JSONObject member=team.getJSONObject("membership");memberId=member.getString("id");role=member.optString("role");uploads=new TeamAudioStore(this,store);}
        catch(Exception e){finish();return;}
        begin("team_audio_loading","Team audio","");task("Loading team…",()->api.get(endpoint("/members")),r->{members=arr(r,"items");String id=getIntent().getStringExtra("meeting_id");if(id!=null&&!id.isEmpty())openAudio(id);else overview();});
    }
    String memberName(String id){for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m.optString("id").equals(id))return m.optString("name");}return "External speaker";}
    boolean manage(){return role.equals("admin")||memberId.equals(meeting.optString("owner_id"));}
    Spinner picker(LinearLayout parent,String caption,String[] values,int selected){label(parent,caption);Spinner p=new Spinner(this);p.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));p.setSelection(Math.max(0,selected));parent.addView(p,new LinearLayout.LayoutParams(-1,dp(50)));return p;}
    static String stage(String value){switch(value){case "uploaded":return "Uploaded";case "normalizing":return "Preparing audio";case "transcribing":return "Transcribing";case "matching":return "Matching speakers";case "needs_identity_review":return "Review speakers";case "analyzing":return "Preparing notes";case "needs_review":return "Ready for review";case "published":return "Published";case "failed":return "Processing failed";default:return value.replace('_',' ');}}
    void overview(){begin("team_audio","Team audio","");content.addView(bold(teamName,26,INK));content.addView(text("Import up to 120 minutes and 250 MiB. Audio is saved in this team space for playback and speaker review.",15,MUTED));
        content.addView(button("Import audio file",true,()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE),410)));
        content.addView(button("Import a phone or JWD recording",false,this::localRecordings));content.addView(button("Import from my library",false,this::cloudRecordings));content.addView(button("Voice profiles",false,this::profiles));content.addView(button("Refresh processing status",false,this::overview));
        if(TeamAudioUploadService.active)content.addView(text(TeamAudioUploadService.message,14,GREEN));
        JSONArray local=uploads.list(teamId);for(int i=0;i<local.length();i++){JSONObject d=local.optJSONObject(i);if(!d.optString("status").equals("uploaded"))feature(d.optString("title"),d.optString("error",TeamAudioUploadService.active?"Uploading":"Saved on this phone · Tap to retry"),()->startUpload(d));}
        task("Loading imports…",()->api.get(endpoint("/meeting-audio-imports")),r->{JSONArray items=arr(r,"items");if(items.length()==0)content.addView(text("No team audio imports yet.",15,MUTED));for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);LinearLayout c=card(content);c.addView(bold(stage(item.optString("stage")),17,INK));JSONObject error=item.optJSONObject("error");if(error!=null)c.addView(text(error.optString("message"),14,MUTED));c.addView(button("Open meeting audio",false,()->openAudio(item.optString("meeting_id"))));if(error!=null&&error.optBoolean("retryable"))c.addView(button("Retry processing",false,()->task("Retrying…",()->api.post(endpoint("/meeting-audio-imports/"+item.optString("id")+"/retry"),json()),x->overview())));}});
    }
    void localRecordings(){begin("team_audio_local","Choose a recording","");JSONArray a=store.drafts();for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d.optString("status").equals("recording"))continue;feature(d.optString("title"),"Phone or JWD audio · Original stays on this phone",()->shareConfirmation(d.optString("title"),Uri.fromFile(new File(d.optString("path")))));}if(a.length()==0)content.addView(text("Record on your phone or download a JWD recording first.",15,MUTED));}
    void cloudRecordings(){begin("team_audio_cloud","My library","");task("Loading recordings…",()->api.get("/api/v1/recordings?limit=100"),r->{JSONArray a=arr(r,"items");for(int i=0;i<a.length();i++){JSONObject rec=a.optJSONObject(i);feature(rec.optString("title"),"Personal audio · Sharing requires confirmation",()->new AlertDialog.Builder(this).setTitle("Share audio with "+teamName+"?").setMessage("Team members will be able to play this audio. Your personal recording will remain in your library.").setNegativeButton("Cancel",null).setPositiveButton("Share audio",(d,w)->task("Importing audio…",()->api.upload(endpoint("/meeting-audio-imports"),null,"",json("recording_id",rec.optString("id"),"client_id","team-audio:"+teamId+":"+rec.optString("id"),"share_with_team","true","title",rec.optString("title"),"language",store.language()),null),result->openAudio(result.optString("meeting_id")))).show());}});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==410&&result==RESULT_OK&&data!=null&&data.getData()!=null)shareConfirmation("Meeting recording",data.getData());}
    void shareConfirmation(String initial,Uri uri){begin("team_audio_share","Share with team","");EditText title=input(content,"Meeting title",initial,false);content.addView(text("Speech language · Automatic",15,MUTED));
        CheckBox consent=new CheckBox(this);consent.setText("Share this audio with "+teamName+". Team members can play it back.");content.addView(consent);
        content.addView(button("Upload to team",true,()->{if(!consent.isChecked()){alert("Confirm sharing","Confirm that this audio can be shared with the team.",null);return;}String name=title.getText().toString().trim();if(name.isEmpty()){alert("Title required","Enter a meeting title.",null);return;}
            task("Saving an upload copy…",()->{String id=UUID.randomUUID().toString();File target=new File(uploads.folder,id+".audio");long size=0;
                try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(target)){if(in==null)throw new IOException("Cannot open this file");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){size+=n;if(size>250L*1024*1024)throw new IOException("Choose a file up to 250 MiB");out.write(buffer,0,n);}}
                catch(Exception e){target.delete();throw e;}if(size==0){target.delete();throw new IOException("The audio file is empty");}
                JSONObject d=json("id",id,"scope",store.scope(),"team_id",teamId,"title",name,"path",target.getAbsolutePath(),"filename","recording.audio","language",store.language(),"status","local");uploads.save(d);return d;},this::startUpload);
        }));
    }
    void startUpload(JSONObject draft){if(TeamAudioUploadService.active){alert("Upload in progress","Wait for the current upload to finish.",null);return;}startForegroundService(new Intent(this,TeamAudioUploadService.class).putExtra("id",draft.optString("id")).putExtra("scope",store.scope()));overview();}
    void openAudio(String id){mid=id;begin("team_audio_detail","Meeting audio","");task("Loading audio…",()->api.get(endpoint("/meetings/"+id)),r->{meeting=r;renderAudio();});}
    void renderAudio(){content.removeAllViews();content.addView(bold(meeting.optString("title"),26,INK));JSONObject audio=meeting.optJSONObject("audio");
        JSONObject processing=meeting.optJSONObject("processing");if(processing!=null)content.addView(text(stage(processing.optString("stage")),14,GREEN));
        if(audio!=null&&audio.optBoolean("ready"))content.addView(button("Play recording",true,()->playSegment(0)));else content.addView(text("Audio is processing. Refresh shortly.",14,MUTED));
        content.addView(button("Refresh",false,()->openAudio(mid)));JSONObject review=meeting.optJSONObject("identity_review");if(review!=null&&!review.optBoolean("can_publish",true))content.addView(text("Confirm every speaker before publishing. Uncertain identities stay in review.",15,MUTED));
        JSONObject doc=meeting.optJSONObject("transcript");JSONArray segments=doc==null?new JSONArray():arr(doc,"segments"),bindings=arr(meeting,"bindings");LinkedHashMap<String,JSONObject> first=new LinkedHashMap<>();for(int i=0;i<segments.length();i++){JSONObject s=segments.optJSONObject(i);first.putIfAbsent(s.optString("speaker_label","unknown"),s);}
        for(Map.Entry<String,JSONObject> entry:first.entrySet()){String label=entry.getKey();JSONObject binding=new JSONObject();for(int i=0;i<bindings.length();i++)if(bindings.optJSONObject(i).optString("label").equals(label))binding=bindings.optJSONObject(i);JSONObject selected=binding,segment=entry.getValue();LinearLayout card=card(content);String status=selected.optString("status","needs_review");
            card.addView(bold(label,18,INK));card.addView(text(status.equals("auto_matched")?"Automatically matched · "+memberName(selected.optString("member_id")):status.equals("confirmed")?"Manually confirmed · "+memberName(selected.optString("member_id")):status.equals("external_confirmed")?"Confirmed external speaker":"Needs review",14,GREEN));card.addView(text(segment.optString("text"),14,MUTED));
            if(audio!=null&&audio.optBoolean("ready"))card.addView(button("Play segment · "+clock(segment.optLong("start_ms")),false,()->playSegment(segment.optInt("start_ms"))));
            if(manage())card.addView(button("Confirm or correct speaker",false,()->confirmSpeaker(label)));
        }
        if(manage()&&audio!=null&&audio.optBoolean("ready"))content.addView(button("Transcribe again",false,()->new AlertDialog.Builder(this).setTitle("Create a new transcript?").setMessage("Previous transcripts and speaker assignments will stay in version history.").setNegativeButton("Cancel",null).setPositiveButton("Transcribe",(d,w)->task("Queuing transcription…",()->api.post(endpoint("/meetings/"+mid+"/retranscribe"),json("version",meeting.optInt("version"))),r->overview())).show()));
        content.addView(button("Back to team imports",false,this::overview));
    }
    void playSegment(int start){JSONObject audio=meeting.optJSONObject("audio");if(audio==null)return;task("Preparing audio…",()->api.get("/api/v1/me"),r->play(store.base()+audio.optString("url"),start,true));}
    void confirmSpeaker(String label){ArrayList<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("Needs review");ids.add("");names.add("Confirmed external speaker");ids.add("external");for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m.optBoolean("active")){names.add(m.optString("name"));ids.add(m.optString("id"));}}
        new AlertDialog.Builder(this).setTitle("Speaker: "+label).setItems(names.toArray(new String[0]),(d,n)->{String id=ids.get(n);JSONObject mapping=json(label,id.isEmpty()||id.equals("external")?JSONObject.NULL:id);JSONArray external=new JSONArray();if(id.equals("external"))external.put(label);task("Saving speaker review…",()->api.request("PUT",endpoint("/meetings/"+mid+"/speakers"),json("version",meeting.optInt("version"),"bindings",mapping,"external_labels",external)),r->openAudio(mid));}).show();
    }
    void profiles(){begin("team_voice","Voice profiles","");content.addView(text("Profiles are private to this team. Automatic matching starts after independent validation. Uncertain speakers remain in review.",15,MUTED));content.addView(button("Refresh profiles",false,this::profiles));
        if(role.equals("admin")){content.addView(button("Create a member profile",true,()->pickMember(id->task("Creating profile…",()->api.post(endpoint("/voice-profiles"),json("member_id",id)),r->profiles()))));content.addView(button("Calibrate and validate",false,()->task("Queuing validation…",()->api.post(endpoint("/voice-profiles/calibrate"),json()),r->alert("Validation queued","Refresh profiles after processing finishes.",null))));}
        task("Loading profiles…",()->api.get(endpoint("/voice-profiles")),r->{JSONObject calibration=r.optJSONObject("calibration");if(calibration!=null)content.addView(text("Latest validation: "+calibration.optString("status"),14,MUTED));JSONArray a=arr(r,"items");for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);LinearLayout c=card(content);c.addView(bold(memberName(p.optString("member_id")),18,INK));c.addView(text(stage(p.optString("status"))+" · "+arr(p,"samples").length()+" samples",14,MUTED));if(role.equals("admin")&&!p.optString("status").equals("revoked"))c.addView(button("Add a confirmed voice clip",false,()->chooseSampleMeeting(p)));if(!p.optString("status").equals("revoked"))c.addView(button("Revoke profile",false,()->new AlertDialog.Builder(this).setTitle("Revoke voice profile?").setMessage("Its samples will be deleted and future matching will stop.").setNegativeButton("Cancel",null).setPositiveButton("Revoke",(d,w)->task("Revoking profile…",()->api.request("DELETE",endpoint("/voice-profiles/"+p.optString("id")),null),x->profiles())).show()));}});
    }
    interface MemberChoice{void choose(String id);}
    void pickMember(MemberChoice choice){ArrayList<String> labels=new ArrayList<>(),ids=new ArrayList<>();for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m.optBoolean("active")){labels.add(m.optString("name"));ids.add(m.optString("id"));}}new AlertDialog.Builder(this).setTitle("Team member").setItems(labels.toArray(new String[0]),(d,n)->choice.choose(ids.get(n))).show();}
    void chooseSampleMeeting(JSONObject profile){begin("voice_source","Select a meeting","");task("Loading meetings…",()->api.get(endpoint("/meetings")),r->{JSONArray a=arr(r,"items");for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);feature(m.optString("title"),"Select manually confirmed speech",()->task("Loading source…",()->api.get(endpoint("/meetings/"+m.optString("id"))),record->sampleForm(profile,record)));}});}
    void sampleForm(JSONObject profile,JSONObject record){begin("voice_sample","Add a confirmed clip","");JSONObject audio=record.optJSONObject("audio"),doc=record.optJSONObject("transcript");if(audio==null||!audio.optBoolean("ready")||doc==null){content.addView(text("Upload this meeting's audio first.",15,MUTED));return;}
        ArrayList<String> labels=new ArrayList<>();JSONArray bindings=arr(record,"bindings");for(int i=0;i<bindings.length();i++){JSONObject b=bindings.optJSONObject(i);if(b.optString("member_id").equals(profile.optString("member_id"))&&b.optString("source").equals("manual")&&!b.isNull("confirmed_by"))labels.add(b.optString("label"));}
        if(labels.isEmpty()){content.addView(text("Manually confirm this member's speaker label first.",15,MUTED));return;}
        content.addView(text("Choose one clear 3–15 second segment without overlapping speech. Use separate recordings for enrollment, calibration and validation.",15,MUTED));
        Spinner label=picker(content,"Confirmed speaker",labels.toArray(new String[0]),0),purpose=picker(content,"Sample use",new String[]{"Enrollment","Calibration","Validation"},0);EditText start=input(content,"Start in seconds","",false),end=input(content,"End in seconds","",false),basis=input(content,"How was this identity confirmed?","",true);
        content.addView(button("Play from start",false,()->{try{int ms=(int)(Double.parseDouble(start.getText().toString())*1000);play(store.base()+audio.optString("url"),ms,true);}catch(Exception e){error(e);}}));
        content.addView(button("Save voice sample",true,()->{try{JSONObject body=json("asset_id",audio.getString("asset_id"),"revision",doc.getInt("revision"),"label",labels.get(label.getSelectedItemPosition()),"start_ms",(int)(Double.parseDouble(start.getText().toString())*1000),"end_ms",(int)(Double.parseDouble(end.getText().toString())*1000),"purpose",new String[]{"enrollment","calibration","validation"}[purpose.getSelectedItemPosition()],"confirmation_basis",basis.getText().toString());task("Saving sample…",()->api.post(endpoint("/voice-profiles/"+profile.optString("id")+"/samples"),body),r->profiles());}catch(Exception e){error(e);}}));
    }
}
